pub type _GetField =
    for <'c> fn(&mut &'c csv::ByteRecord, &usize) -> Option<&'c [u8]>;

impl Selection {
    pub fn select<'a, 'b>(&'a self, row: &'b csv::ByteRecord)
                 -> iter::Scan<
                        slice::Iter<'a, usize>,
